using Microsoft.Win32;

namespace PaperWindow;

internal static class Program
{
    [STAThread]
    static void Main()
    {
        using var mutex = new Mutex(true, @"Local\PaperWindow.SingleInstance", out bool first);
        if (!first) return;

        ApplicationConfiguration.Initialize();
        Application.Run(new PaperContext());
    }
}

/// <summary>The newspaper icon (assets\paper.ico, generated by tools\make-icon.ps1), picked at the requested size.</summary>
internal static class AppIcon
{
    public static Icon Get(Size size)
    {
        using var stream = typeof(AppIcon).Assembly.GetManifestResourceStream("paper.ico")!;
        return new Icon(stream, size);
    }
}

/// <summary>Tray app: screen-wide color filter + paper grain overlay on every monitor, driven by <see cref="Settings"/>.</summary>
internal sealed class PaperContext : ApplicationContext
{
    readonly bool _firstRun = !Settings.Exists;
    readonly Settings _settings = Settings.Load();
    readonly NotifyIcon _tray;
    readonly ToolStripMenuItem _toggleItem;
    readonly ToolStripMenuItem _profilesItem = new("Perfil");
    readonly HotkeyManager _hotkeys = new();
    readonly System.Windows.Forms.Timer _topmostTimer = new() { Interval = 2000 };
    readonly System.Windows.Forms.Timer _scheduleTimer = new() { Interval = 30_000 };
    readonly List<OverlayForm> _overlays = new();
    readonly InkLayer _ink = new();   // ink trail and ink drops
    readonly bool _magReady;
    string? _overlayTexture;   // texture id the current overlays were built with; null when none are open
    string? _scheduleKey;      // period + profile the schedule last applied; null when it has not applied anything yet
    SettingsForm? _settingsForm;

    public PaperContext()
    {
        _magReady = Native.MagInitialize();
        // A previous run that crashed may have left themed cursors installed; the system ones come back here,
        // and on an unexpected crash of this run as well.
        CursorTheme.Restore();
        AppDomain.CurrentDomain.UnhandledException += (_, _) => CursorTheme.Restore();

        _toggleItem = new ToolStripMenuItem("Efeito papel ativo", null, (_, _) => ToggleEnabled());
        var menu = new ContextMenuStrip();
        menu.Items.Add(new ToolStripMenuItem("Configurações...", null, (_, _) => ShowSettings())
        {
            Font = new Font(menu.Font, FontStyle.Bold),
        });
        menu.Items.Add(_toggleItem);
        menu.Items.Add(_profilesItem);
        _profilesItem.DropDownItems.Add(new ToolStripMenuItem());   // placeholder so the submenu arrow shows
        _profilesItem.DropDownOpening += (_, _) => BuildProfilesMenu();
        menu.Items.Add(new ToolStripSeparator());
        menu.Items.Add("Sair", null, (_, _) => ExitThread());

        _tray = new NotifyIcon
        {
            Icon = AppIcon.Get(SystemInformation.SmallIconSize),
            Text = "Paper Window",
            ContextMenuStrip = menu,
            Visible = true,
        };
        _tray.DoubleClick += (_, _) => ShowSettings();

        _topmostTimer.Tick += (_, _) =>
        {
            _overlays.ForEach(o => o.KeepOnTop());
            _ink.KeepOnTop();
        };
        SystemEvents.DisplaySettingsChanged += OnDisplayChanged;
        SystemEvents.TimeChanged += OnTimeChanged;
        SystemEvents.PowerModeChanged += OnPowerModeChanged;
        _scheduleTimer.Tick += (_, _) => CheckSchedule();
        _scheduleTimer.Start();
        _hotkeys.Pressed += ToggleEnabled;

        CheckSchedule();
        Apply();
        if (_firstRun) ShowSettings();
        else if (_hotkeys.Failed)
            _tray.ShowBalloonTip(5000, "Paper Window",
                $"O atalho {_settings.ToggleHotkey} já está em uso por outro programa. Escolha outro nas configurações.",
                ToolTipIcon.Warning);
    }

    /// <summary>Brings the color filter, overlays, mouse effects and hotkey in line with the current settings.</summary>
    void Apply()
    {
        _toggleItem.Checked = _settings.Enabled;
        var p = _settings.Shown;
        float[] matrix = ColorMatrix();
        SetColorMatrix(matrix);
        CursorTheme.Apply(_settings.Enabled && p.CursorTheme ? CursorStyles.Find(p.CursorStyle) : null, matrix);
        _ink.Configure(_settings.Enabled && p.InkTrail, p.InkTrailLength * 15, p.InkTrailWidth,
            _settings.Enabled && p.InkDrop, _settings.HideMouseFromCapture);

        Hotkey.TryParse(_settings.ToggleHotkey, out var hotkey);
        _hotkeys.Set(hotkey);
        _toggleItem.ShortcutKeyDisplayString = hotkey?.ToString();

        string? wanted = _settings.Enabled ? _settings.Shown.Texture : null;
        if (wanted != _overlayTexture)
        {
            CloseOverlays();
            if (wanted != null) OpenOverlays(TextureStyles.Find(wanted));
        }
        foreach (var o in _overlays)
        {
            o.SetOpacity(OverlayAlpha);
            o.SetCaptureExcluded(_settings.HideTextureFromCapture);
        }
        _topmostTimer.Enabled = _settings.Enabled;
    }

    byte OverlayAlpha => (byte)(Math.Clamp(_settings.Shown.TextureOpacity, 0, 100) * 255 / 100);

    void ToggleEnabled()
    {
        _settings.Enabled = !_settings.Enabled;
        SaveAndApply();
    }

    void BuildProfilesMenu()
    {
        _profilesItem.DropDownItems.Clear();
        foreach (var p in _settings.Profiles)
        {
            string name = p.Name;
            _profilesItem.DropDownItems.Add(new ToolStripMenuItem(name, null, (_, _) => SwitchProfile(name))
            {
                Checked = p == _settings.Current,
            });
        }
        if (_settings.ScheduleEnabled)
        {
            bool night = _settings.IsNight(DateTime.Now.TimeOfDay);
            _profilesItem.DropDownItems.Add(new ToolStripSeparator());
            _profilesItem.DropDownItems.Add(new ToolStripMenuItem(
                $"Agendado agora: {(night ? "Noite" : "Dia")} ({(night ? _settings.NightProfile : _settings.DayProfile)})")
            {
                Enabled = false,
            });
        }
    }

    /// <summary>
    /// Switches to the scheduled profile when the period (day/night) or the profile chosen for it changes.
    /// A profile picked by hand stays until the next change. Waits while the active profile has unsaved edits.
    /// </summary>
    void CheckSchedule()
    {
        var now = DateTime.Now.TimeOfDay;
        string? wanted = _settings.ScheduledProfile(now);
        if (wanted == null)
        {
            _scheduleKey = null;
            return;
        }
        string key = $"{_settings.IsNight(now)}|{wanted}";
        if (key == _scheduleKey) return;
        if (wanted == _settings.ActiveProfile)
        {
            _scheduleKey = key;
            return;
        }
        if (_settings.HasUnsavedChanges) return;   // try again on the next tick
        _scheduleKey = key;
        _settings.DiscardDraft();
        _settings.ActiveProfile = wanted;
        SaveAndApply();
    }

    void OnTimeChanged(object? sender, EventArgs e) => CheckSchedule();

    void OnPowerModeChanged(object? sender, PowerModeChangedEventArgs e)
    {
        if (e.Mode == PowerModes.Resume) CheckSchedule();
    }

    void SwitchProfile(string name)
    {
        // With the window open, it may hold unsaved edits: let it ask before switching.
        if (_settingsForm is { IsDisposed: false })
        {
            _settingsForm.Activate();
            _settingsForm.SwitchProfile(name);
            return;
        }
        _settings.ActiveProfile = name;
        SaveAndApply();
    }

    void SaveAndApply()
    {
        _settings.Save();
        _settingsForm?.RefreshControls();
        Apply();
    }

    void ShowSettings()
    {
        if (_settingsForm is { IsDisposed: false })
        {
            _settingsForm.Activate();
            return;
        }
        // Schedule edits in the window take effect right away; posted so the switch does not refresh the
        // window's controls from inside their own change events.
        _settingsForm = new SettingsForm(_settings, _hotkeys, () =>
        {
            Apply();
            SynchronizationContext.Current?.Post(_ => CheckSchedule(), null);
        });
        _settingsForm.FormClosed += (_, _) => _settingsForm = null;
        _settingsForm.Show();
        _settingsForm.Activate();
    }

    void OpenOverlays(TextureStyle style)
    {
        foreach (var screen in Screen.AllScreens)
        {
            var overlay = new OverlayForm(screen.Bounds, style, OverlayAlpha);
            overlay.Show();
            _overlays.Add(overlay);
        }
        _overlayTexture = style.Id;
    }

    void CloseOverlays()
    {
        foreach (var o in _overlays) o.Dispose();
        _overlays.Clear();
        _overlayTexture = null;
    }

    void OnDisplayChanged(object? sender, EventArgs e)
    {
        CloseOverlays();
        Apply();
    }

    /// <summary>The screen color matrix for the shown look (identity when the effect is off).</summary>
    float[] ColorMatrix()
    {
        var p = _settings.Shown;
        return _settings.Enabled
            ? ColorEffects.Dim(
                ColorEffects.ReduceBlueLight(
                    ColorEffects.Matrix(ColorEffects.Find(p.Effect), Math.Clamp(p.FilterStrength, 0, 100) / 100f),
                    Math.Clamp(p.BlueLightFilter, 0, 100) / 100f),
                Math.Clamp(p.Brightness, Profile.MinBrightness, 100) / 100f)
            : ColorEffects.Identity();
    }

    void SetColorMatrix(float[] m)
    {
        if (!_magReady) return;
        var effect = new Native.MAGCOLOREFFECT { Transform = m };
        Native.MagSetFullscreenColorEffect(ref effect);
    }

    protected override void ExitThreadCore()
    {
        // The window may ask to save unsaved edits; "Cancelar" there means "don't quit".
        _settingsForm?.Close();
        if (_settingsForm is { IsDisposed: false }) return;

        SystemEvents.DisplaySettingsChanged -= OnDisplayChanged;
        SystemEvents.TimeChanged -= OnTimeChanged;
        SystemEvents.PowerModeChanged -= OnPowerModeChanged;
        _hotkeys.Dispose();
        _topmostTimer.Dispose();
        _scheduleTimer.Dispose();
        _ink.Dispose();
        CursorTheme.Restore();
        CloseOverlays();
        SetColorMatrix(ColorEffects.Identity());
        if (_magReady) Native.MagUninitialize();
        _tray.Visible = false;
        _tray.Dispose();
        base.ExitThreadCore();
    }
}
